                    LMS_ContentFiles obj = new LMS_ContentFiles();
                    dtbTable = obj.GetDataTable("LMS_ContentFiles_SearchCbx");
                    DataRow drw = dtbTable.NewRow();
                    dtbTable.Rows.InsertAt(drw, 0); // thêm dòng trống
