        public static bool Delete(long fileID)
        {
            LMS_ContentFiles obj = new LMS_ContentFiles();
            obj.FileID = fileID;
            if (obj.Delete())
            {
                HaveNewData = true;
                return true;
            }
            return false;
        }

        #endregion
    }
